WHERE i.warehouse_id IN
#{warehouseId}
AND w.company_id = #{bo.companyId}
AND i.warehouse_id = #{bo.warehouseId}
AND l.zone_id = #{bo.zoneId}
AND i.location_id = #{bo.locationId}
AND m.material_code LIKE CONCAT('%', #{bo.materialCode}, '%')
AND m.material_name LIKE CONCAT('%', #{bo.materialName}, '%')
AND m.category_id = #{bo.categoryId}
AND i.quantity = 0
AND i.quantity > 0
